import 'package:forui/forui.dart';
import 'package:material_ui/material_ui.dart';

part 'colors.dart';
part 'typography.dart';
part 'style.dart';
part 'icons.dart';

/// Generated by Forui CLI.
///
/// Regenerate using "dart run forui theme create --preset eabbbc", then restore
/// the hand edits documented in `docs/ui.md` (primary `#F6AD49`, dark
/// destructive / error foregrounds, and `_bottomNavigationBarStyle`).
///
/// Modify the generated function bodies to create your own custom style.
/// Then, call the modified function and pass it to [FTheme].
///
/// You can also generate styles to be used in the generated [FThemeData] using:
/// ```shell
/// dart run forui style create [styles]
/// ```
///
/// See:
/// * https://forui.dev/docs/guides/customizing-themes for customizing themes.
/// * https://forui.dev/docs/guides/customizing-widget-styles for customizing individual widget styles.
FThemeData get lightTheme {
  // Change this to false to use the desktop variant of this theme.
  const touch = true;

  final colors = lightColors;

  final typography = _typography(colors: colors, touch: touch);

  final icons = _icons();

  final style = _style(colors: colors, typography: typography, touch: touch);

  return FThemeData(
    colors: colors,
    typography: typography,
    icons: icons,
    style: style,
    touch: touch,
    bottomNavigationBarStyle: _bottomNavigationBarStyle(
      colors: colors,
      typography: typography,
      style: style,
    ),
  );
}

FThemeData get darkTheme {
  // Change this to false to use the desktop variant of this theme.
  const touch = true;

  final colors = darkColors;

  final typography = _typography(colors: colors, touch: touch);

  final icons = _icons();

  final style = _style(colors: colors, typography: typography, touch: touch);

  return FThemeData(
    colors: colors,
    typography: typography,
    icons: icons,
    style: style,
    touch: touch,
    bottomNavigationBarStyle: _bottomNavigationBarStyle(
      colors: colors,
      typography: typography,
      style: style,
    ),
  );
}

/// ブランド primary は `#F6AD49` のまま、選択タブだけ前景色でコントラストを確保する。
FBottomNavigationBarStyle _bottomNavigationBarStyle({
  required FColors colors,
  required FTypography typography,
  required FStyle style,
}) {
  return FBottomNavigationBarStyle.inherit(
    colors: colors,
    typography: typography,
    style: style,
  ).copyWith(
    itemStyle:
        FBottomNavigationBarItemStyle.inherit(
          colors: colors,
          typography: typography,
          style: style,
        ).copyWith(
          iconStyle: FVariants.from(
            IconThemeData(color: colors.mutedForeground, size: 24),
            variants: {
              [.hovered, .pressed]: .delta(
                color: colors.hover(colors.mutedForeground),
              ),
              [.selected]: .delta(color: colors.foreground, weight: 700),
            },
          ),
          textStyle: FVariants.from(
            typography.body.xs3.copyWith(
              color: colors.mutedForeground,
              height: 1.5,
            ),
            variants: {
              [.hovered, .pressed]: .delta(
                color: colors.hover(colors.mutedForeground),
              ),
              [.selected]: .delta(color: colors.foreground, fontWeight: .bold),
            },
          ),
        ),
  );
}
